"""Builds the Polish project guide as one HTML page with embedded figures. Run: python src/guide_build.py <out.html>

Only extra_numbers.json is read at build time; the tables (TUNED, XFER, RULE, GRAPHS, TARGETS) and many sentences carry
numbers transcribed by hand from data/processed/*.json at the time they were written. When a number changes, update this
script too, or the guide drifts from the model card.
"""
import base64, html, json, pathlib, sys

F = pathlib.Path("figures"); D = pathlib.Path("data/processed")
ex = json.load(open(D / "extra_numbers.json")); gain = lambda p, g: next(r for r in ex["gains"] if r["platform"] == p and r["model"] == g)["gain vs base"]
c = lambda v, d=3: f"{v:+.{d}f}".replace(".", ",")


def img(name, alt):
    b = base64.b64encode((F / name).read_bytes()).decode(); return f'<img src="data:image/png;base64,{b}" alt="{html.escape(alt)}" loading="lazy">'


def fig(name, title, what, see, so):
    return f'<figure><h3>{title}</h3>{img(name, title)}<dl><dt>Co jest na wykresie</dt><dd>{what}</dd><dt>Na co patrzeć</dt><dd>{see}</dd><dt>Wniosek</dt><dd class="so">{so}</dd></dl></figure>'


def table(head, rows):
    return '<div class="tw"><table><thead><tr>' + "".join(f"<th>{h}</th>" for h in head) + "</tr></thead><tbody>" + "".join("<tr>" + "".join(f"<td>{x}</td>" for x in r) + "</tr>" for r in rows) + "</tbody></table></div>"


def box(title, *body):
    return f'<section class="box"><h3>{title}</h3>' + "".join(body) + "</section>"


