GRAPHS = table(["Graf", "Jak powstaje", "Jaka cecha trafia do modelu", "Zysk TikTok / YouTube / X"], [
    ["Tekst kNN", "Wzmianka to węzeł. Krawędź do 10 najbardziej podobnych tekstów (cosinus na TF-IDF)", "Struktura: wielkość społeczności, PageRank, klasteryzacja, liczba bliskich kopii", "−0,001 / +0,002 / −0,002"], ["Embedding spektralny", "Ten sam graf, 8 wektorów własnych", "Położenie posta w grafie", "0,000 / +0,006 / +0,005"], ["Społeczności (Louvain)", "Podział grafu tekstu na gęste grupy", "Średni błąd modelu w społeczności, tylko z uczenia", "−0,001 / 0,000 / +0,005"], ["Społeczności marek", "Graf marek po podobieństwie ich tekstów", "Średni błąd w społeczności marek, bez własnej marki", "−0,001 / −0,001 / +0,005"], ["Autor–marka", "Graf dwudzielny: autor łączy się z markami, o których pisze", "Ile marek i wzmianek ma autor, stopień marki", "−0,001 / −0,003 / −0,005"], ["Hashtagi", "Posty łączy wspólny hashtag", "Średni błąd postów z tym samym hashtagiem", "0,000 / +0,002 / +0,003"], ["Czas", "Posty z tej samej platformy w oknie ±3 dni", "Średni błąd w oknie", "0,000 / −0,003 / +0,002"], ["Bliskie kopie", "Cosinus powyżej 0,8", "Czy post ma kopię i jaki błąd mają kopie", "0,000 / +0,001 / 0,000"], ["Propagacja etykiet", "Błędy z uczenia rozlewane po grafie na 2 kroki", "Wygładzony błąd sąsiadów", "−0,004 / −0,004 / −0,021"], ["Wszystko razem", "Wszystkie powyższe", "", "+0,003 / +0,003 / +0,002"]])
TARGETS = table(["Co przewidujemy", "TikTok R²", "YouTube R²", "X R²"], [["lajki", "0,76", "0,72", "0,59"], ["komentarze", "0,68", "0,73", "0,49"], ["udostępnienia", "0,75", "brak danych", "0,62"], ["followersi", "0,22", "0,44", "0,15"]])
GLOSS = "".join(f"<div><b>{a}</b>{b}</div>" for a, b in [("Wyświetlenia vs zasięg", "Wyświetlenia to liczba odsłon od platformy. Zasięg Brand24 to ich szacunek. Na TikToku i YouTube obie liczby są równe. Czy to ten sam byt, pytamy Brand24."), ("Reakcje", "Lajki + komentarze + udostępnienia."), ("log10", "Skala, w której każda jednostka to 10× więcej. Potrzebna, bo wyświetlenia sięgają od 1 do milionów."), ("MAE (błąd)", "Średnia pomyłka w log10. 0,3 ≈ pomyłka ×2, 0,5 ≈ ×3, 1,0 ≈ ×10."), ("CV po markach", "Uczenie na części marek i test na markach, których model nie widział."), ("Przedział ufności", "Zakres niepewności wyniku z losowania marek ze zwracaniem (bootstrap). Na wykresach to wąsy."), ("Strojenie", "Szukanie najlepszych ustawień modelu (hiperparametrów). Testowa część danych nie bierze w tym udziału."), ("Kappa", "Zgodność dwóch kodujących po odjęciu przypadku. 0,6–0,8 = dobra."), ("Ablacja", "Sprawdzanie, co się stanie, gdy usuniemy kawałek modelu.")])

